// CSD_RATIONALE_BEGIN
// GSM-symbolic revision. The prior attempt hit two failure modes:
//   (a) runaway repetition outside constrained spans (e.g. long `!!!!!!`
//       tails) that drove "too_slow" budget exceedance.
//   (b) malformed/non-canonical constrained content (use of `min`, `ceil`,
//       float `/`, etc. instead of integer arithmetic).
// Fixes:
//   - Strengthen the task guidance to forbid functions and require `//` for
//     integer division so the symbolic content matches evaluator expectations.
//   - Detect runaway token repetition outside the span (same token N times in
//     a row) and abort to free up wall-clock budget.
//   - Keep adaptive constrained generation with `<<` penalised inside spans
//     and EOS handling unchanged.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   - Outside branch: flipping to `inside` only on next == "<<", with
//     currentConstrainedOut := [], valid by parser.IsValidPrefix([]).
//   - Complete branch: CloseConstrainedSpan flips insideConstrainedOut to
//     false, making the implication vacuous.
//   - Constrained-step branch: AdaptiveConstrainedStepWithPenalties returns
//     EOS (we break) or a parser-valid next token; AppendConstrainedToken
//     extends a valid prefix by a valid token, preserving validity.
//   - Repetition-abort branch breaks the loop without changing constrained
//     state, preserving the implication.
// progress:
//   - Each iteration consumes exactly one token-step (steps += 1) and appends
//     at most one visible token, so |generated| <= |generatedPrefix| + steps
//     holds. Repetition tracking is bookkeeping only.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(
  lm,
  "Solve step by step. Wrap every intermediate calculation and the final numeric answer inside << and >> delimiters, e.g., <<3+4=7>>. Use only integer arithmetic: + - * and // (floor division). Do NOT use functions like min, max, ceil, floor, round, or abs. Do NOT use float division /. Keep each <<...>> expression short. Put the final answer in one final <<...>> at the end."
);

var steps: nat := 0;
var lastTok: Token := "";
var repeatCount: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
        lastTok := "";
        repeatCount := 0;
      } else {
        if next == lastTok {
          repeatCount := repeatCount + 1;
          if repeatCount >= 5 {
            break;
          }
        } else {
          lastTok := next;
          repeatCount := 0;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    lastTok := "";
    repeatCount := 0;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStepWithPenalties(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 3.0,
      ["<<", "min", "max", "ceil", "floor", "round", "abs"], 6.0,
      12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

